import{_ as a,c as o,a0 as t,o as i}from"./chunks/framework.B6JXc2q-.js";const u=JSON.parse('{"title":"v1.1.8：认证身份一致性与保活诊断","description":"","frontmatter":{},"headers":[],"relativePath":"release/v1.1.8.md","filePath":"release/v1.1.8.md"}'),l={name:"release/v1.1.8.md"};function r(c,e,d,n,s,p){return i(),o("div",null,e[0]||(e[0]=[t('<h1 id="v1-1-8-认证身份一致性与保活诊断" tabindex="-1">v1.1.8：认证身份一致性与保活诊断 <a class="header-anchor" href="#v1-1-8-认证身份一致性与保活诊断" aria-label="Permalink to &quot;v1.1.8：认证身份一致性与保活诊断&quot;">​</a></h1><p>日期：2026-11-22。版本入口：<code>pyproject.toml</code>、<code>xiaomusic/__init__.py</code>。</p><h2 id="用户可见变化" tabindex="-1">用户可见变化 <a class="header-anchor" href="#用户可见变化" aria-label="Permalink to &quot;用户可见变化&quot;">​</a></h2><p>扫码与续期沿用同一 UA 和设备标识，降低跨请求身份不一致风险。长期凭据年龄作为普通信息显示，不再在60小时后建议扫码；续期被拒或需要人工认证时仍明确警告，当前播放运行时可用性独立展示。</p><p>成功保活每轮清零连续失败计数；连续三次失败进入退化后，首次成功只记录一次恢复。诊断包含实际探测、门禁、结果类别、连续失败数与进程内累计计数。<code>probe_failure_total</code> 统计有实际探测且最终失败的保活轮次；<code>gate_skip_total</code> 统计无实际探测且存在门禁的失败轮次。计数随进程重启归零。</p><p>保留12小时调度、验证后原子CAS、扫码凭据代际校验、拒绝空值/删除标记及禁止隐式密码登录。验证恢复清理旧cooldown/backoff，但普通运行时恢复不解除长期续期挂起门。</p><p>可选cookie观测不再记录凭据指纹、长度或异常原文；健康探测错误只保留网络/认证类别。历史观测文档已脱敏并修正过强因果结论。容器默认时区采用Asia/Tokyo。</p><h2 id="已有运行证据" tabindex="-1">已有运行证据 <a class="header-anchor" href="#已有运行证据" aria-label="Permalink to &quot;已有运行证据&quot;">​</a></h2><p>11月6日扫码的测试候选持续约15天20小时，31次计划触发均有换票及验证后CAS提交；长期凭据未轮换，容器重启计数0，最后提交为11月22日02:20:29 JST。</p><p>这是单账号、单周期观察，支持身份一致性方案有效；单次保活失败原因仍未知。75条不健康警告和25条恢复记录受旧计数缺陷影响，不能据其数量直接判断网络故障或凭据失效。</p><h2 id="本地验收" tabindex="-1">本地验收 <a class="header-anchor" href="#本地验收" aria-label="Permalink to &quot;本地验收&quot;">​</a></h2><ul><li>Python 3.11：认证、扫码、CAS、诊断、日志脱敏等14个测试文件，<strong>190 passed</strong>。</li><li>播放契约及来源插件CI门禁：<strong>25 passed</strong>。</li><li>Node 24：WebUI 16个测试文件，<strong>78 passed</strong>；TypeScript检查和Vite生产构建通过。</li><li>共享挂载不支持npm所需符号链接，因此前端在 <code>/tmp/r118-webui</code> 的源码副本安装依赖并验证，未修改lockfile。</li><li>Ruff：新增收尾代码检查通过；<code>qrcode_login.py</code> 有8项历史问题（导入、类型写法及异常链），本次未扩展清理。</li></ul><p>认证测试清单已加入 <code>.github/workflows/contract-gates.yml</code>，与既有播放及前端门禁一起运行。</p><h2 id="分支整合" tabindex="-1">分支整合 <a class="header-anchor" href="#分支整合" aria-label="Permalink to &quot;分支整合&quot;">​</a></h2><ul><li><code>chore/api-boundary-phase1</code> 的64c3ac4c与main的56fae1fe补丁等价。</li><li><code>chore/webui-command-state-decouple</code> 的9c1f2d8a与main的95ae6e4d补丁等价；不重复合并已存在代码。</li><li>其余认证、发布和Node Actions本地分支均已是main祖先。</li><li><code>wip/local-main-snapshot-20260912</code> 的主体已拆入39ea4c2e、73007676、e31674b8。补入其恢复后清cooldown/backoff的有效回归意图，保留旧快照与迁移bundle，不用旧版本覆盖当前main。</li><li>本地one-shot脚本测试及11月1日MiPlay实验文档属于独立实验，保留但不纳入本次发布。</li></ul><h2 id="尚未验证及后续" tabindex="-1">尚未验证及后续 <a class="header-anchor" href="#尚未验证及后续" aria-label="Permalink to &quot;尚未验证及后续&quot;">​</a></h2><p>本版新增年龄显示、计数和诊断尚未部署服务器；没有执行完整仓库测试或多架构Docker构建。npm审计报告8项依赖漏洞（3 moderate、3 high、2 critical），未自动升级依赖；需独立评估开发/运行路径与升级兼容性。构建另有两项字体路径运行时解析提示，测试输出含既有依赖/pytest警告。</p><p>GitHub main推送与CI结果由交付记录另行确认；本文不预先宣称远端成功。未创建发布tag或触发镜像Release，也未访问正式服。后续部署前保留旧镜像，回滚只更换程序，不恢复旧认证文件覆盖用户新扫码数据。</p>',18)]))}const m=a(l,[["render",r]]);export{u as __pageData,m as default};
